import React, { useState, useEffect } from 'react';
import './Admin.css';

function Admin({ allerVers, utilisateur }) {
  const [donnees, setDonnees] = useState(null);
  const [chargement, setChargement] = useState(true);
  const [onglet, setOnglet] = useState('stats');
  const [messageAction, setMessageAction] = useState('');

  const chargerDonnees = () => {
    fetch('/api/admin/stats')
      .then(res => res.json())
      .then(data => {
        setDonnees(data);
        setChargement(false);
      })
      .catch(() => setChargement(false));
  };

  useEffect(() => {
    if (!utilisateur || utilisateur.role !== 'admin') {
      allerVers('accueil');
      return;
    }
    chargerDonnees();
  }, [utilisateur]);

  const traiterRetrait = async (retraitId, statut) => {
    try {
      const reponse = await fetch('/api/admin/retrait', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ retrait_id: retraitId, statut })
      });
      const donnees = await reponse.json();
      setMessageAction('✅ ' + donnees.message);
      chargerDonnees();
      setTimeout(() => setMessageAction(''), 3000);
    } catch (erreur) {
      setMessageAction('❌ Erreur lors du traitement');
    }
  };

  const bloquerUtilisateur = async (utilisateurId, bloquer) => {
    try {
      const reponse = await fetch('/api/admin/bloquer', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ utilisateur_id: utilisateurId, bloquer })
      });
      const donnees = await reponse.json();
      setMessageAction('✅ ' + donnees.message);
      chargerDonnees();
      setTimeout(() => setMessageAction(''), 3000);
    } catch (erreur) {
      setMessageAction('❌ Erreur');
    }
  };

  if (chargement) return (
    <div className="admin-page">
      <div className="chargement">Chargement...</div>
    </div>
  );

  return (
    <div className="admin-page">
      <header className="header">
        <div className="logo" onClick={() => allerVers('accueil')}>🎵 Varim Music</div>
        <nav className="nav">
          <a href="#" onClick={() => allerVers('accueil')}>Accueil</a>
          <a href="#" className="actif">Admin</a>
        </nav>
        <div className="auth-buttons">
          <span className="user-prenom">👑 {utilisateur?.prenom}</span>
          <button className="btn-login" onClick={() => {
            localStorage.removeItem('token');
            localStorage.removeItem('utilisateur');
            allerVers('accueil');
          }}>Déconnexion</button>
        </div>
      </header>

      <div className="admin-contenu">
        <h1 className="admin-titre">👑 Panel Admin</h1>

        {messageAction && (
          <div className="admin-message-action">{messageAction}</div>
        )}

        {/* STATS */}
        <div className="stats-grille">
          <div className="stat-carte">
            <div className="stat-icone">👥</div>
            <div className="stat-valeur">{donnees?.stats?.total_utilisateurs}</div>
            <div className="stat-label">Utilisateurs</div>
          </div>
          <div className="stat-carte">
            <div className="stat-icone">🎤</div>
            <div className="stat-valeur">{donnees?.stats?.total_artistes}</div>
            <div className="stat-label">Artistes</div>
          </div>
          <div className="stat-carte">
            <div className="stat-icone">🎧</div>
            <div className="stat-valeur">{donnees?.stats?.total_acheteurs}</div>
            <div className="stat-label">Acheteurs</div>
          </div>
          <div className="stat-carte">
            <div className="stat-icone">🎵</div>
            <div className="stat-valeur">{donnees?.stats?.total_musiques}</div>
            <div className="stat-label">Musiques</div>
          </div>
          <div className="stat-carte">
            <div className="stat-icone">🛒</div>
            <div className="stat-valeur">{donnees?.stats?.total_achats}</div>
            <div className="stat-label">Ventes</div>
          </div>
          <div className="stat-carte revenus">
            <div className="stat-icone">💰</div>
            <div className="stat-valeur">{donnees?.stats?.total_commissions} FCFA</div>
            <div className="stat-label">Mes commissions</div>
          </div>
        </div>

        {donnees?.stats?.retraits_en_attente > 0 && (
          <div className="alerte-retraits" onClick={() => setOnglet('retraits')}>
            ⚠️ <strong>{donnees?.stats?.retraits_en_attente} retrait(s)</strong> en attente de traitement → Cliquez pour gérer
          </div>
        )}

        {/* ONGLETS */}
        <div className="admin-onglets">
          <button className={`onglet ${onglet === 'stats' ? 'actif' : ''}`} onClick={() => setOnglet('stats')}>
            🔔 Dernières ventes
          </button>
          <button className={`onglet ${onglet === 'retraits' ? 'actif' : ''}`} onClick={() => setOnglet('retraits')}>
            💸 Retraits {donnees?.stats?.retraits_en_attente > 0 && `(${donnees?.stats?.retraits_en_attente})`}
          </button>
          <button className={`onglet ${onglet === 'utilisateurs' ? 'actif' : ''}`} onClick={() => setOnglet('utilisateurs')}>
            👥 Utilisateurs
          </button>
          <button className={`onglet ${onglet === 'artistes' ? 'actif' : ''}`} onClick={() => setOnglet('artistes')}>
            🎤 Top Artistes
          </button>
        </div>

        {/* DERNIÈRES VENTES */}
        {onglet === 'stats' && (
          <div className="admin-section">
            <h2>🔔 Dernières ventes</h2>
            {donnees?.ventes?.length === 0 ? (
              <div className="vide">Aucune vente.</div>
            ) : (
              <table className="admin-table">
                <thead>
                  <tr>
                    <th>Musique</th>
                    <th>Type</th>
                    <th>Acheteur</th>
                    <th>Artiste</th>
                    <th>Montant</th>
                    <th>Commission</th>
                    <th>Opérateur</th>
                    <th>Date</th>
                  </tr>
                </thead>
                <tbody>
                  {donnees?.ventes?.map(vente => (
                    <tr key={vente.id}>
                      <td>{vente.titre}</td>
                      <td><span className="badge">{vente.type}</span></td>
                      <td>{vente.acheteur_prenom}</td>
                      <td>{vente.artiste_prenom}</td>
                      <td className="montant">{vente.montant} FCFA</td>
                      <td className="commission">{vente.commission} FCFA</td>
                      <td><span className={`operateur ${vente.operateur}`}>{vente.operateur?.toUpperCase()}</span></td>
                      <td>{new Date(vente.date_achat).toLocaleDateString('fr-FR')}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        )}

        {/* GESTION DES RETRAITS */}
        {onglet === 'retraits' && (
          <div className="admin-section">
            <h2>💸 Gestion des retraits</h2>
            {donnees?.retraits?.length === 0 ? (
              <div className="vide">Aucun retrait.</div>
            ) : (
              <table className="admin-table">
                <thead>
                  <tr>
                    <th>Date</th>
                    <th>Artiste</th>
                    <th>Téléphone</th>
                    <th>Opérateur</th>
                    <th>Montant</th>
                    <th>Numéro retrait</th>
                    <th>Statut</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {donnees?.retraits?.map(retrait => (
                    <tr key={retrait.id}>
                      <td>{new Date(retrait.date_demande).toLocaleDateString('fr-FR')}</td>
                      <td>{retrait.artiste_prenom}</td>
                      <td>{retrait.telephone}</td>
                      <td><span className={`operateur ${retrait.operateur}`}>{retrait.operateur?.toUpperCase()}</span></td>
                      <td className="montant">{retrait.montant} FCFA</td>
                      <td>+242 {retrait.numero_retrait}</td>
                      <td>
                        <span className={`statut ${retrait.statut}`}>
                          {retrait.statut === 'en_attente' ? '⏳ En attente' :
                           retrait.statut === 'traite' ? '✅ Traité' : '❌ Annulé'}
                        </span>
                      </td>
                      <td>
                        {retrait.statut === 'en_attente' && (
                          <div className="actions-retrait">
                            <button
                              className="btn-traiter"
                              onClick={() => traiterRetrait(retrait.id, 'traite')}
                            >
                              ✅ Traité
                            </button>
                            <button
                              className="btn-annuler-retrait"
                              onClick={() => traiterRetrait(retrait.id, 'annule')}
                            >
                              ❌ Annuler
                            </button>
                          </div>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        )}

        {/* UTILISATEURS */}
        {onglet === 'utilisateurs' && (
          <div className="admin-section">
            <h2>👥 Utilisateurs</h2>
            <table className="admin-table">
              <thead>
                <tr>
                  <th>Prénom</th>
                  <th>Téléphone</th>
                  <th>Rôle</th>
                  <th>Date inscription</th>
                  <th>Statut</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {donnees?.utilisateurs?.map(u => (
                  <tr key={u.id}>
                    <td>{u.prenom}</td>
                    <td>{u.telephone}</td>
                    <td><span className={`badge ${u.role}`}>{u.role}</span></td>
                    <td>{new Date(u.date_inscription).toLocaleDateString('fr-FR')}</td>
                    <td>
                      <span className={u.bloque ? 'statut annule' : 'statut traite'}>
                        {u.bloque ? '🚫 Bloqué' : '✅ Actif'}
                      </span>
                    </td>
                    <td>
                      {u.role !== 'admin' && (
                        <button
                          className={u.bloque ? 'btn-traiter' : 'btn-annuler-retrait'}
                          onClick={() => bloquerUtilisateur(u.id, !u.bloque)}
                        >
                          {u.bloque ? '✅ Débloquer' : '🚫 Bloquer'}
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* TOP ARTISTES */}
        {onglet === 'artistes' && (
          <div className="admin-section">
            <h2>🎤 Top Artistes</h2>
            <table className="admin-table">
              <thead>
                <tr>
                  <th>Rang</th>
                  <th>Artiste</th>
                  <th>Téléphone</th>
                  <th>Musiques</th>
                  <th>Ventes</th>
                  <th>Revenus artiste</th>
                </tr>
              </thead>
              <tbody>
                {donnees?.topArtistes?.map((artiste, index) => (
                  <tr key={artiste.id}>
                    <td>#{index + 1}</td>
                    <td>🎤 {artiste.prenom}</td>
                    <td>{artiste.telephone}</td>
                    <td>{artiste.nb_musiques}</td>
                    <td>{artiste.nb_ventes}</td>
                    <td className="montant">{artiste.revenus} FCFA</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

export default Admin;
